# Check connectivity of 9s (4-connected)
from collections import deque

def find_connected_components_9():
    visited = set()
    components = []

    for start_r, start_c in nonzero[9]:
        if (start_r, start_c) in visited:
            continue

        comp = []
        queue = deque([(start_r, start_c)])

        while queue:
            r, c = queue.popleft()
            if (r, c) in visited:
                continue
            visited.add((r, c))
            comp.append((r, c))

            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 10 and 0 <= nc < 20:
                    if grid[nr][nc] == 9 and (nr, nc) not in visited:
                        queue.append((nr, nc))

        components.append(comp)

    return components

